        return point3d(*this) *= t;
    }
    point3d operator/(ftype t) const {
        return point3d(*this) /= t;
    }
};
point3d operator*(ftype a, point3d b) {
    return b * a;
}
```

Bu yerda `ftype` koordinatalar uchun ishlatiladigan tur bo‘lib, odatda `int`, `long long` yoki `double` tanlanadi. Butun koordinatalar va faqat qo‘shish, ayirish, ko‘paytirish talab qilinadigan masalalarda butun tur aniq natija beradi. Bo‘lish, uzunlik va burchaklar ishlatilganda odatda `double` zarur bo‘ladi.

## Skalyar ko‘paytma

### Ta’rif

$\mathbf a$ va $\mathbf b$ vektorlarning skalyar ko‘paytmasi geometrik jihatdan

$$
\mathbf a\cdot\mathbf b=|\mathbf a|\,|\mathbf b|\cos\theta,
$$

bu yerda $\theta$ — vektorlar orasidagi burchak. Boshqacha aytganda, birinchi vektor uzunligi ikkinchi vektorning birinchi vektor yo‘nalishidagi proyeksiyasi uzunligiga ko‘paytiriladi.

Skalyar ko‘paytma quyidagi muhim xossalarga ega:

1. $\mathbf a\cdot\mathbf b=\mathbf b\cdot\mathbf a$;
2. $(\alpha\mathbf a)\cdot\mathbf b=\alpha(\mathbf a\cdot\mathbf b)$;
3. $(\mathbf a+\mathbf b)\cdot\mathbf c=\mathbf a\cdot\mathbf c+\mathbf b\cdot\mathbf c$.

Koordinatalarda

$$
(x_1,y_1)\cdot(x_2,y_2)=x_1x_2+y_1y_2,
$$

uch o‘lchamda esa

$$
(x_1,y_1,z_1)\cdot(x_2,y_2,z_2)=x_1x_2+y_1y_2+z_1z_2.
$$

```cpp
ftype dot(point2d a, point2d b) {
    return a.x * b.x + a.y * b.y;
}
ftype dot(point3d a, point3d b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}
```

Masalalarda qiymatni hisoblash uchun algebraik ta’rif ishlatiladi, lekin formulani qo‘llash yo‘lini ko‘rish uchun geometrik ma’noni yodda tutish kerak.

### Xossalar va qo‘llanishlar

Skalyar ko‘paytma orqali ko‘plab geometrik kattaliklar aniqlanadi:

1. kvadrat norma: $|\mathbf a|^2=\mathbf a\cdot\mathbf a$;
2. uzunlik: $|\mathbf a|=\sqrt{\mathbf a\cdot\mathbf a}$;
3. $\mathbf a$ ning $\mathbf b$ yo‘nalishidagi skalyar proyeksiyasi: $\dfrac{\mathbf a\cdot\mathbf b}{|\mathbf b|}$;
4. vektorlar orasidagi burchak: $\arccos\dfrac{\mathbf a\cdot\mathbf b}{|\mathbf a||\mathbf b|}$;
5. skalyar ko‘paytma musbat bo‘lsa burchak o‘tkir, manfiy bo‘lsa o‘tmas, nol bo‘lsa vektorlar o‘zaro perpendikulyar.

```cpp
ftype norm(point2d a) {
    return dot(a, a);
}
double abs(point2d a) {
    return sqrt(norm(a));
}
double proj(point2d a, point2d b) {
    return dot(a, b) / abs(b);
}
double angle(point2d a, point2d b) {
    return acos(dot(a, b) / abs(a) / abs(b));
}
```

$\mathbf r\cdot\mathbf a=C$ tenglamani qanoatlantiradigan barcha $\mathbf r$ nuqtalar $\mathbf a$ ga perpendikulyar gipertekislikni hosil qiladi. Ikki o‘lchamda bu to‘g‘ri chiziq, uch o‘lchamda tekislikdir. Shuning uchun 2D chiziqni

$$
\mathbf r\cdot\mathbf n=C
$$

yoki

$$
(\mathbf r-\mathbf r_0)\cdot\mathbf n=0
$$

ko‘rinishda berish mumkin. Bu yerda $\mathbf n$ chiziqqa normal vektor, $\mathbf r_0$ esa chiziqdagi istalgan nuqta.

## Vektor ko‘paytma

### Uch o‘lchamli ta’rif

$\mathbf b\times\mathbf c$ vektor $\mathbf b$ va $\mathbf c$ ga perpendikulyar bo‘lib, uning uzunligi shu ikki vektor quradigan parallelogramm yuziga teng:

$$
|\mathbf b\times\mathbf c|=|\mathbf b|\,|\mathbf c|\sin\theta.
$$

Yo‘nalish o‘ng qo‘l qoidasi bilan tanlanadi. $\mathbf a\cdot(\mathbf b\times\mathbf c)$ aralash ko‘paytma deyiladi; uning moduli uch vektor quradigan parallelepiped hajmiga teng.

Muhim xossalar:

1. $\mathbf a\times\mathbf b=-\mathbf b\times\mathbf a$;
2. $(\alpha\mathbf a)\times\mathbf b=\alpha(\mathbf a\times\mathbf b)$;
3. $(\mathbf a+\mathbf b)\times\mathbf c=\mathbf a\times\mathbf c+\mathbf b\times\mathbf c$;
4. $\mathbf a\cdot(\mathbf b\times\mathbf c)=\mathbf b\cdot(\mathbf c\times\mathbf a)=\mathbf c\cdot(\mathbf a\times\mathbf b)$;
5. ikki vektor kollinear bo‘lsa va faqat shunda ularning vektor ko‘paytmasi nol.

Koordinatalarda:

$$
\mathbf a\times\mathbf b=
\begin{pmatrix}
 a_yb_z-a_zb_y\\
 a_zb_x-a_xb_z\\
 a_xb_y-a_yb_x
\end{pmatrix}.
$$

```cpp
point3d cross(point3d a, point3d b) {
    return point3d(a.y * b.z - a.z * b.y,
                   a.z * b.x - a.x * b.z,
                   a.x * b.y - a.y * b.x);
}
ftype triple(point3d a, point3d b, point3d c) {
    return dot(a, cross(b, c));
}
```

### Ikki o‘lchamli vektor ko‘paytma

Ikki o‘lchamli vektorlarni $z=0$ tekisligiga joylashtirsak, ularning vektor ko‘paytmasi faqat $z$ koordinataga ega bo‘ladi. Shu sababli 2D da skalyar qiymat sifatida

$$
\operatorname{cross}(\mathbf a,\mathbf b)=a_xb_y-a_yb_x
$$

ishlatiladi.

```cpp
ftype cross(point2d a, point2d b) {
    return a.x * b.y - a.y * b.x;
}
```

Bu qiymatning moduli vektorlar quradigan parallelogramm yuziga teng. Ishora esa burilish yo‘nalishini ko‘rsatadi: musbat qiymat $\mathbf a$ dan $\mathbf b$ ga soat miliga teskari burilishni, manfiy qiymat soat mili bo‘yicha burilishni bildiradi.

Uchta $a,b,c$ nuqta uchun

$$
\operatorname{cross}(b-a,c-a)
$$

qiymati uchburchakning ikki baravar yo‘nalgan yuzidir. U nol bo‘lsa nuqtalar bir chiziqda; musbat bo‘lsa $a\to b\to c$ chap burilish, manfiy bo‘lsa o‘ng burilish hosil qiladi.

## Chiziqlar kesishishi

Ikki o‘lchamda chiziqni nuqta va yo‘nalish vektori bilan

$$
\mathbf r=\mathbf a+t\mathbf d
$$

ko‘rinishda berish mumkin. Ikki chiziq

$$
\mathbf a_1+t\mathbf d_1=\mathbf a_2+s\mathbf d_2
$$

kesishsa, vektor ko‘paytmadan

$$
t=\frac{(\mathbf a_2-\mathbf a_1)\times\mathbf d_2}{\mathbf d_1\times\mathbf d_2}
$$

kelib chiqadi. Maxraj nol bo‘lsa yo‘nalishlar parallel. Surat ham nol bo‘lsa chiziqlar ustma-ust tushadi; aks holda ular turli parallel chiziqlardir.

```cpp
point2d intersect(point2d a1, point2d d1,
                  point2d a2, point2d d2) {
    return a1 + cross(a2 - a1, d2) / cross(d1, d2) * d1;
}
```

Uch o‘lchamda ikki chiziq odatda bir tekislikda bo‘lmasligi mumkin. Ularning komplanarligi aralash ko‘paytma bilan tekshiriladi:

$$
(\mathbf a_2-\mathbf a_1)\cdot(\mathbf d_1\times\mathbf d_2)=0.
$$

## Tekisliklar kesishishi

Tekislik normal vektor va undagi nuqta orqali

$$
(\mathbf r-\mathbf r_0)\cdot\mathbf n=0
$$

ko‘rinishda beriladi. Ikki parallel bo‘lmagan tekislikning kesishmasi yo‘nalishi $\mathbf n_1\times\mathbf n_2$ bo‘lgan chiziqdir. Uchta tekislikning yagona kesishish nuqtasini Kramer qoidasi yoki aralash ko‘paytma orqali topish mumkin.

Quyidagi formula $\mathbf r\cdot\mathbf n_i=d_i$ ($i=1,2,3$) tekisliklarning kesishish nuqtasini beradi:

$$
\mathbf r=
\frac{
 d_1(\mathbf n_2\times\mathbf n_3)+
 d_2(\mathbf n_3\times\mathbf n_1)+
 d_3(\mathbf n_1\times\mathbf n_2)
}{
 \mathbf n_1\cdot(\mathbf n_2\times\mathbf n_3)
}.
$$

Maxraj nol bo‘lsa normal vektorlar chiziqli bog‘liq va yagona kesishish nuqtasi mavjud emas.

Geometrik algoritmlarda koordinata turi va sonli xatolarni tanlash juda muhim. Butun koordinatalarda orientatsiya va kesishish shartlarini imkon qadar `long long` yoki kengroq butun turda hisoblash kerak. Haqiqiy sonlarda esa tenglik o‘rniga masala o‘lchamiga mos `EPS` bilan taqqoslash qo‘llanadi.

# Kesma uchun to‘g‘ri chiziq tenglamasini topish

Tekislikda uchlari $(x_1,y_1)$ va $(x_2,y_2)$ bo‘lgan kesma berilgan. Shu ikki nuqtadan o‘tuvchi cheksiz to‘g‘ri chiziqning

$$
ax+by+c=0
$$

ko‘rinishdagi tenglamasini topish talab qilinadi.

## Ikki nuqtadan chiziq tenglamasini chiqarish

Chiziq bo‘ylab yo‘nalish vektori

$$
\mathbf d=(x_2-x_1,\ y_2-y_1)
$$

bo‘ladi. Chiziqning normal vektori unga perpendikulyar bo‘lishi kerak. Masalan,

$$
\mathbf n=(y_1-y_2,\ x_2-x_1)
$$

vektorni olish mumkin, chunki

$$
(x_2-x_1)(y_1-y_2)+(y_2-y_1)(x_2-x_1)=0.
$$

Shuning uchun

$$
a=y_1-y_2,\qquad b=x_2-x_1.
$$

Chiziq birinchi nuqtadan o‘tishi uchun

$$
a x_1+b y_1+c=0,
$$

demak

$$
c=-a x_1-b y_1=x_1y_2-x_2y_1.
$$

Natijada tayyor formula:

$$
\boxed{
 a=y_1-y_2,\qquad
 b=x_2-x_1,\qquad
 c=x_1y_2-x_2y_1
}
$$

bo‘ladi.

Bu koeffitsiyentlarni istalgan nol bo‘lmagan songa bir vaqtda ko‘paytirish yoki bo‘lish chiziqni o‘zgartirmaydi. Masalan, $(a,b,c)$ va $(ka,kb,kc)$ bir xil geometrik chiziqni ifodalaydi.

## Butun koordinatalar uchun implementatsiya

Agar kirish koordinatalari butun bo‘lsa, koeffitsiyentlarni ham butun sonlarda hisoblash mumkin. Koordinatalar katta bo‘lishi mumkinligi sababli ko‘paytmalarga `long long` ishlatish ma’qul.

```cpp
struct point {
    long long x, y;
};

struct line {
    long long a, b, c;
};

line line_from_segment(point p, point q) {
    line l;
    l.a = p.y - q.y;
    l.b = q.x - p.x;
    l.c = p.x * q.y - q.x * p.y;
    return l;
}
```

Koeffitsiyentlarni kanonik ko‘rinishga keltirish kerak bo‘lsa, $g=\gcd(|a|,|b|,|c|)$ ga bo‘lish mumkin. So‘ng birinchi nol bo‘lmagan koeffitsiyent musbat bo‘lishi uchun uchalasining ishorasi bir vaqtda almashtiriladi. Bu chiziqlarni taqqoslash yoki `set`/`map` kaliti sifatida saqlashda qulay.

```cpp
line normalize(line l) {
    long long g = std::gcd(std::gcd(llabs(l.a), llabs(l.b)), llabs(l.c));
    if (g != 0) {
        l.a /= g;
        l.b /= g;
        l.c /= g;
    }
    if (l.a < 0 || (l.a == 0 && l.b < 0) ||
        (l.a == 0 && l.b == 0 && l.c < 0)) {
        l.a = -l.a;
        l.b = -l.b;
        l.c = -l.c;
    }
    return l;
}
```

## Maxsus holatlar

Agar ikkala uch bir xil nuqta bo‘lsa, $a=b=c=0$ chiqadi va bu to‘g‘ri chiziqni aniqlamaydi. Masala shartida kesma uzunligi musbat ekanini tekshirish yoki bu degenerativ holatni alohida qayta ishlash kerak.

Vertikal chiziqda $x_1=x_2$ bo‘ladi. Formula avtomatik ravishda $b=0$ va $a\ne0$ beradi; chiziq $x=x_1$ ko‘rinishga keladi. Gorizontal chiziqda esa $a=0$ bo‘lib, $y=y_1$ hosil bo‘ladi. Shu sababli qiyalik $k$ ishlatadigan $y=kx+b$ ko‘rinishidan farqli ravishda $ax+by+c=0$ barcha yo‘nalishlar uchun bir xil ishlaydi.

Nuqtaning chiziqning qaysi tomonida yotishini $ax+by+c$ iforasi ishorasi orqali aniqlash mumkin. Qiymat nol bo‘lsa nuqta chiziqda, musbat va manfiy qiymatlar esa chiziqning ikki turli tomonini bildiradi.

# To‘g‘ri chiziqlarning kesishish nuqtasi

Tekislikda ikkita to‘g‘ri chiziq berilgan. Ularning yagona kesishish nuqtasini topish yoki chiziqlar parallel ekanini aniqlash kerak. Chiziqlar

$$
a_1x+b_1y+c_1=0,
\qquad
a_2x+b_2y+c_2=0
$$

ko‘rinishda beriladi.

## Determinant yordamida yechim

Ikki tenglamali chiziqli sistema uchun determinant

$$
D=a_1b_2-a_2b_1
$$

bo‘ladi. Agar $D\ne0$ bo‘lsa, Kramer qoidasiga ko‘ra yagona kesishish nuqtasi mavjud:

$$
x=-\frac{c_1b_2-c_2b_1}{D},
\qquad
y=-\frac{a_1c_2-a_2c_1}{D}.
$$

Ekvivalent ko‘rinish:

$$
x=\frac{b_1c_2-b_2c_1}{D},
\qquad
y=\frac{c_1a_2-c_2a_1}{D}.
$$

Agar $D=0$ bo‘lsa, normal vektorlar proporsional va chiziqlar parallel. Bu holatda chiziqlar yo turli, yo ustma-ust tushadi. Masalan,

$$
a_1c_2-a_2c_1=0,
\qquad
b_1c_2-b_2c_1=0
$$

ham bajarilsa, chiziqlar ustma-ust tushadi.

## Haqiqiy sonlar uchun tuzilma

Quyidagi tuzilma ikki nuqtadan chiziq quradi va koeffitsiyentlarni $\sqrt{a^2+b^2}=1$ bo‘ladigan qilib normallashtiradi. Normallashtirish nuqtadan chiziqqacha masofa kabi amallarni soddalashtiradi.

```cpp
const double EPS = 1e-9;

struct pt {
    double x, y;
};

struct line {
    double a, b, c;

    line() {}

    line(pt p, pt q) {
        a = p.y - q.y;
        b = q.x - p.x;
        c = -a * p.x - b * p.y;
        norm();
    }

    void norm() {
        double z = sqrt(a * a + b * b);
        if (z > EPS) {
            a /= z;
            b /= z;
            c /= z;
        }
    }
};
```

Ikki chiziqning determinanti va kesishish nuqtasi:

```cpp
double det(double a, double b, double c, double d) {
    return a * d - b * c;
}

bool intersect(line m, line n, pt &res) {
    double zn = det(m.a, m.b, n.a, n.b);
    if (abs(zn) < EPS)
        return false;
    res.x = -det(m.c, m.b, n.c, n.b) / zn;
    res.y = -det(m.a, m.c, n.a, n.c) / zn;
    return true;
}
```

`intersect` `false` qaytarsa, yagona nuqta yo‘q; parallel va ustma-ust holatlarni alohida ajratish mumkin.

```cpp
bool parallel(line m, line n) {
    return abs(det(m.a, m.b, n.a, n.b)) < EPS;
}

bool equivalent(line m, line n) {
    return abs(det(m.a, m.b, n.a, n.b)) < EPS &&
           abs(det(m.a, m.c, n.a, n.c)) < EPS &&
           abs(det(m.b, m.c, n.b, n.c)) < EPS;
}
```

## Parametrik ko‘rinish

Chiziqlar nuqta va yo‘nalish vektori orqali ham berilishi mumkin:

$$
p+t\,r,
\qquad q+u\,s.
$$

Ular parallel bo‘lmasa,

$$
t=\frac{(q-p)\times s}{r\times s}
$$

va kesishish nuqtasi $p+tr$ ga teng.

```cpp
struct vec {
    double x, y;
    vec operator+(vec other) const { return {x + other.x, y + other.y}; }
    vec operator-(vec other) const { return {x - other.x, y - other.y}; }
    vec operator*(double k) const { return {x * k, y * k}; }
};

double cross(vec a, vec b) {
    return a.x * b.y - a.y * b.x;
}

bool line_intersection(vec p, vec r, vec q, vec s, vec &ans) {
    double d = cross(r, s);
    if (abs(d) < EPS)
        return false;
    double t = cross(q - p, s) / d;
    ans = p + r * t;
    return true;
}
```

## Sonli aniqlik

`double` bilan ishlaganda determinant mutlaq nolga tenglashtirilmaydi; `abs(D) < EPS` kabi tekshiruv qo‘llanadi. `EPS` koordinatalar miqyosiga bog‘liq. Juda katta koordinatalarda nisbiy xatoni ham hisobga olish yoki imkon bo‘lsa butun determinantlar va ratsional javobdan foydalanish kerak.

Agar kirish koeffitsiyentlari butun bo‘lsa, parallel ekanini `__int128` da aniq tekshirish mumkin. Kesishish koordinatalari kasr bo‘lishi mumkin, shuning uchun javobni ratsional sonlar jufti yoki `long double` orqali saqlash tanlanadi.

# Ikki kesma kesishishini tekshirish

$(a,b)$ va $(c,d)$ kesmalar berilgan. Ular kamida bitta umumiy nuqtaga egami, shuni tekshirish kerak. Kesishish nuqtasining o‘zini topish shart emas. Butun koordinatalarda ishlaydigan usul ayniqsa qulay, chunki barcha tekshiruvlar vektor ko‘paytma va bir o‘lchamli oraliqlar kesishishiga keltiriladi.

## Algoritm

Avval kesmalar bir chiziqda yotadigan holatni ko‘ramiz. Agar $a,b,c,d$ kollinear bo‘lsa, kesmalar kesishishi uchun ularning $Ox$ o‘qidagi proyeksiyalari ham, $Oy$ o‘qidagi proyeksiyalari ham kesishishi yetarli va zarur.

Kollinear bo‘lmagan holatda $a$ va $b$ nuqtalar $(c,d)$ chiziqning qat’iy bir tomonida yotmasligi, shu bilan birga $c$ va $d$ nuqtalar $(a,b)$ chiziqning qat’iy bir tomonida yotmasligi kerak. Tomonlar orientatsiya qiymatlari bilan aniqlanadi:

$$
\operatorname{orient}(a,b,p)=(b-a)\times(p-a).
$$

Shuning uchun umumiy shart:

$$
\operatorname{sgn}(\operatorname{orient}(a,b,c))
\ne
\operatorname{sgn}(\operatorname{orient}(a,b,d))
$$

va

$$
\operatorname{sgn}(\operatorname{orient}(c,d,a))
\ne
\operatorname{sgn}(\operatorname{orient}(c,d,b)).
$$

Nol qiymat kesma uchining boshqa kesma chizig‘ida yotishini bildiradi va tegish holatini ham kesishish deb hisoblash imkonini beradi.

## Implementatsiya

Quyidagi kod butun koordinatalar uchun yozilgan. Koordinatalar ko‘paytmasi `long long` diapazonidan chiqmasligi kerak; katta chegaralarda `__int128` ishlatiladi.

```cpp
struct pt {
    long long x, y;
    pt() {}
    pt(long long _x, long long _y) : x(_x), y(_y) {}
    pt operator-(const pt& p) const { return pt(x - p.x, y - p.y); }
    long long cross(const pt& p) const { return x * p.y - y * p.x; }
    long long cross(const pt& a, const pt& b) const {
        return (a - *this).cross(b - *this);
    }
};

int sgn(const long long& x) {
    return x >= 0 ? x ? 1 : 0 : -1;
}

bool inter1(long long a, long long b, long long c, long long d) {
    if (a > b)
        swap(a, b);
    if (c > d)
        swap(c, d);
    return max(a, c) <= min(b, d);
}

bool check_inter(const pt& a, const pt& b,
                 const pt& c, const pt& d) {
    if (c.cross(a, d) == 0 && c.cross(b, d) == 0)
        return inter1(a.x, b.x, c.x, d.x) &&
               inter1(a.y, b.y, c.y, d.y);
    return sgn(a.cross(b, c)) != sgn(a.cross(b, d)) &&
           sgn(c.cross(d, a)) != sgn(c.cross(d, b));
}
```

`inter1` yopiq oraliqlar kesishishini tekshiradi. `<=` ishlatilgani sababli faqat bitta umumiy uchga ega kesmalar ham kesishuvchi deb olinadi.

## To‘g‘rilik asoslanishi

Agar kesmalar kollinear bo‘lsa, ularning har biri bitta chiziqdagi yopiq intervaldir. Ikki o‘lchamli koordinatalardan kamida bittasi chiziq bo‘ylab qat’iy o‘zgaradi; ikkala koordinata proyeksiyasining kesishishi umumiy nuqta mavjudligini aniq ifodalaydi.

Kollinear bo‘lmagan kesmalarda $(a,b)$ chiziq tekislikni ikki yarim tekislikka bo‘ladi. $(c,d)$ kesma bu chiziqni kesishi uchun uning uchlari turli yarim tekisliklarda yoki chiziqning o‘zida bo‘lishi kerak. Xuddi shu shart ikkinchi chiziq uchun ham bajarilganda kesmalar chiziqlar kesishgan nuqtaga ikkalasi ham yetib boradi. Shu sababli ikki juft orientatsiya ishorasi sharti zarur va yetarli.

## Murakkablik

Algoritm doimiy sondagi arifmetik amal bajaradi, ya’ni vaqt murakkabligi $O(1)$ va qo‘shimcha xotira $O(1)$.

# Kesmalar kesishmasi

Tekislikda $[a,b]$ va $[c,d]$ yopiq kesmalar berilgan. Ularning kesishmasini topish kerak. Natija uch xil bo‘lishi mumkin:

1. kesishma bo‘sh;
2. kesishma bitta nuqta;
3. kesmalar kollinear va ularning kesishmasi yana bir kesma.

Maqoladagi yondashuv haqiqiy koordinatalarda ishlaydi va chiziqlar tenglamasi, proyeksiyalar hamda `EPS` yordamida degenerativ holatlarni qayta ishlaydi.

## Yordamchi tuzilmalar

```cpp
const double EPS = 1E-9;

struct pt {
    double x, y;

    bool operator<(const pt& p) const {
        return x < p.x - EPS ||
               (abs(x - p.x) < EPS && y < p.y - EPS);
    }
};

struct line {
    double a, b, c;

    line() {}
    line(pt p, pt q) {
        a = p.y - q.y;
        b = q.x - p.x;
        c = -a * p.x - b * p.y;
        norm();
    }

    void norm() {
        double z = sqrt(a * a + b * b);
        if (abs(z) > EPS)
            a /= z, b /= z, c /= z;
    }

    double dist(pt p) const {
        return a * p.x + b * p.y + c;
    }
};
```

Nuqtalarni leksikografik taqqoslash kesma uchlarini bir xil tartibga keltirish va kollinear kesishmani topish uchun ishlatiladi. Chiziq koeffitsiyentlari normallashtirilgani sababli `dist` ishorali masofani beradi.

Determinant va bir o‘lchamli oraliqlar kesishishi:

```cpp
double det(double a, double b, double c, double d) {
    return a * d - b * c;
}

bool betw(double l, double r, double x) {
    return min(l, r) <= x + EPS && x <= max(l, r) + EPS;
}

bool intersect_1d(double a, double b, double c, double d) {
    if (a > b) swap(a, b);
    if (c > d) swap(c, d);
    return max(a, c) <= min(b, d) + EPS;
}
```

Ikki parallel bo‘lmagan chiziqning kesishish nuqtasi:

```cpp
pt intersect_lines(line m, line n) {
    double zn = det(m.a, m.b, n.a, n.b);
    return {
        -det(m.c, m.b, n.c, n.b) / zn,
        -det(m.a, m.c, n.a, n.c) / zn
    };
}
```

## Asosiy algoritm

Natijani `left` va `right` nuqtalar orqali qaytaramiz. Bitta nuqta kesishmasida ular teng bo‘ladi; kesma kesishmasida ular kesishma kesmaning uchlaridir.

```cpp
bool intersect(pt a, pt b, pt c, pt d, pt& left, pt& right) {
    if (!intersect_1d(a.x, b.x, c.x, d.x) ||
        !intersect_1d(a.y, b.y, c.y, d.y))
        return false;

    line m(a, b);
    line n(c, d);
    double zn = det(m.a, m.b, n.a, n.b);

    if (abs(zn) < EPS) {
        if (abs(m.dist(c)) > EPS || abs(n.dist(a)) > EPS)
            return false;

        if (b < a) swap(a, b);
        if (d < c) swap(c, d);
        left = max(a, c);
        right = min(b, d);
        return true;
    }

    left = right = intersect_lines(m, n);
    return betw(a.x, b.x, left.x) &&
           betw(a.y, b.y, left.y) &&
           betw(c.x, d.x, left.x) &&
           betw(c.y, d.y, left.y);
}
```

Avval $x$ va $y$ proyeksiyalar kesishishi tekshiriladi. Bu tez rad etish bilan birga kollinear holatda ham zarur shartdir.

Agar determinant nolga yaqin bo‘lsa, chiziqlar parallel. Bir chiziqdagi nuqtaning ikkinchi chiziqqacha ishorali masofasi ham nolga yaqin bo‘lmasa, ular turli parallel chiziqlar va kesishma yo‘q. Aks holda kesmalar kollinear. Uchlar leksikografik tartibga keltirilib, kesishma $[\max(a,c),\min(b,d)]$ sifatida olinadi.

Determinant nol bo‘lmasa, chiziqlar yagona nuqtada kesishadi. Shu nuqta ikkala kesmaning koordinata oraliqlarida yotsa, u kesmalar kesishmasidir.

## Degenerativ kesmalar

Kesmalardan biri nuqta bo‘lsa, chiziqning normalizatsiyasi nol uzunlik sababli alohida e’tibor talab qiladi. Amaliy implementatsiyada avval `a == b` va `c == d` holatlarini ajratish, nuqtaning kesmada yotishini orientatsiya va koordinata oraliqlari bilan tekshirish xavfsizroq.

## Murakkablik

Barcha amallar doimiy vaqtda bajariladi: vaqt $O(1)$, qo‘shimcha xotira $O(1)$.

# Aylana va to‘g‘ri chiziq kesishmasi

Markazi koordinatalar boshida, radiusi $r$ bo‘lgan aylana va

$$
ax+by+c=0
$$

to‘g‘ri chiziq berilgan. Ularning kesishish nuqtalarini topish talab qilinadi. Markazi boshqa nuqtada bo‘lgan aylana uchun avval koordinatalarni markazga siljitish, javobdan so‘ng nuqtalarni orqaga siljitish kifoya.

## Geometrik yechim

Koordinatalar boshidan chiziqqa tushirilgan perpendikulyarning asosini $(x_0,y_0)$ deb belgilaymiz. Chiziq normal vektori $(a,b)$ bo‘lgani uchun eng yaqin nuqta shu yo‘nalishda yotadi. Standart proyeksiya formulasi:

$$
x_0=-\frac{ac}{a^2+b^2},
\qquad
y_0=-\frac{bc}{a^2+b^2}.
$$

Koordinatalar boshidan chiziqqacha masofaning kvadrati

$$
d_0^2=\frac{c^2}{a^2+b^2}
$$

bo‘ladi.

Uch holat mavjud:

1. $d_0>r$ bo‘lsa, chiziq aylana tashqarisidan o‘tadi va kesishma yo‘q;
2. $d_0=r$ bo‘lsa, chiziq urinma va yagona nuqta $(x_0,y_0)$;
3. $d_0<r$ bo‘lsa, ikkita kesishish nuqtasi mavjud.

Uchinchi holatda kesishish nuqtalarining $(x_0,y_0)$ dan chiziq bo‘ylab masofasi

$$
d=\sqrt{r^2-d_0^2}
$$

ga teng. Chiziqning birlik yo‘nalish vektori

$$
\frac{(-b,a)}{\sqrt{a^2+b^2}}
$$

bo‘lgani uchun siljish komponentlari

$$
\Delta x=-b\sqrt{\frac{r^2-d_0^2}{a^2+b^2}},
\qquad
\Delta y=a\sqrt{\frac{r^2-d_0^2}{a^2+b^2}}
$$

bo‘ladi. Javoblar:

$$
(x_0+\Delta x,y_0+\Delta y),
\qquad
(x_0-\Delta x,y_0-\Delta y).
$$

## Implementatsiya

```cpp
const double EPS = 1e-9;

struct point {
    double x, y;
};

vector<point> circle_line_intersection(double r,
                                       double a,
                                       double b,
                                       double c) {
    vector<point> ans;
    double den = a * a + b * b;
    double x0 = -a * c / den;
    double y0 = -b * c / den;
    double lhs = c * c;
    double rhs = r * r * den;

    if (lhs > rhs + EPS)
        return ans;

    if (abs(lhs - rhs) < EPS) {
        ans.push_back({x0, y0});
        return ans;
    }

    double mult = sqrt((rhs - lhs) / den) / sqrt(den);
    double ax = x0 + b * mult;
    double ay = y0 - a * mult;
    double bx = x0 - b * mult;
    double by = y0 + a * mult;
    ans.push_back({ax, ay});
    ans.push_back({bx, by});
    return ans;
}
```

Formulani quyidagicha ham yozish mumkin:

```cpp
double d = r * r - c * c / (a * a + b * b);
double mult = sqrt(d / (a * a + b * b));
point p1 = {x0 + b * mult, y0 - a * mult};
point p2 = {x0 - b * mult, y0 + a * mult};
```

Haqiqiy sonlarda $d$ nazariy jihatdan nol bo‘lsa ham hisoblash xatosi sababli ozgina manfiy chiqishi mumkin. Shuning uchun holatlarni `EPS` bilan ajratib, `sqrt` ga uzatishdan oldin $d$ ni kamida nolga tenglashtirish mumkin.

## Nega geometrik usul afzal

Aylana tenglamasi $x^2+y^2=r^2$ ga chiziq tenglamasidan bir o‘zgaruvchini qo‘yib, kvadrat tenglama yechish ham mumkin. Biroq bu usul ko‘proq algebraik amallarni talab qiladi va ayrim yo‘nalishlarda, masalan $b\approx0$ bo‘lganda, alohida shartlar yoki sonli beqarorlik keltirib chiqaradi. Perpendikulyar proyeksiyaga asoslangan formula simmetrik, qisqa va barcha chiziq yo‘nalishlari uchun bir xil ishlaydi.

## Siljitilgan aylana

Aylana markazi $(x_c,y_c)$ bo‘lsa, $X=x-x_c$, $Y=y-y_c$ deb olamiz. Chiziq

$$
aX+bY+(ax_c+by_c+c)=0
$$

ko‘rinishga keladi. Yuqoridagi algoritmda yangi $c'=ax_c+by_c+c$ ishlatiladi va topilgan $(X,Y)$ nuqtalarga markaz qo‘shiladi.

Murakkablik $O(1)$ vaqt va $O(1)$ qo‘shimcha xotiradir.

# Ikki aylananing kesishmasi

Markazlari $(x_1,y_1)$ va $(x_2,y_2)$, radiuslari $r_1$ va $r_2$ bo‘lgan ikki aylananing umumiy nuqtalarini topish kerak.

## Koordinatalarni siljitish

Avval birinchi aylana markazini koordinatalar boshiga ko‘chiramiz:

$$
(x_2',y_2')=(x_2-x_1,\ y_2-y_1).
$$

Endi aylana tenglamalari

$$
x^2+y^2=r_1^2
$$

va

$$
(x-x_2')^2+(y-y_2')^2=r_2^2
$$

bo‘ladi. Ikkinchi tenglamadan birinchisini ayirsak, kvadrat hadlar yo‘qoladi:

$$
-2x x_2'-2y y_2'+x_2'^2+y_2'^2=r_2^2-r_1^2.
$$

Bu

$$
Ax+By+C=0
$$

chiziq tenglamasi bo‘lib,

$$
A=-2x_2',\qquad
B=-2y_2',\qquad
C=x_2'^2+y_2'^2+r_1^2-r_2^2.
$$

Demak, ikki aylana kesishishi masalasi markazi boshda va radiusi $r_1$ bo‘lgan aylananing shu chiziq bilan kesishishiga keltiriladi.

## Maxsus holatlar

Agar markazlar bir xil bo‘lsa, ya’ni $x_2'=y_2'=0$:

- $r_1=r_2$ bo‘lsa, aylanalar ustma-ust tushadi va cheksiz ko‘p umumiy nuqta mavjud;
- radiuslar turli bo‘lsa, umumiy nuqta yo‘q.

Markazlar turli bo‘lsa, umumiy nuqtalar sonini markazlar orasidagi $d$ masofa orqali ham aniqlash mumkin:

- $d>r_1+r_2$ — aylanalar tashqi tomondan ajralgan;
- $d<|r_1-r_2|$ — bir aylana ikkinchisining ichida va tegmaydi;
- $d=r_1+r_2$ yoki $d=|r_1-r_2|$ — bitta urinma nuqta;
- $|r_1-r_2|<d<r_1+r_2$ — ikkita kesishish nuqtasi.

## Implementatsiya

```cpp
const double EPS = 1e-9;

struct point {
    double x, y;
};

struct circle_intersection_result {
    // infinite == true bo‘lsa aylanalar ustma-ust tushadi.
    bool infinite = false;
    vector<point> points;
};

circle_intersection_result intersect_circles(point c1, double r1,
                                             point c2, double r2) {
    circle_intersection_result res;
    double x2 = c2.x - c1.x;
    double y2 = c2.y - c1.y;

    if (abs(x2) < EPS && abs(y2) < EPS) {
        if (abs(r1 - r2) < EPS)
            res.infinite = true;
        return res;
    }

    double A = -2.0 * x2;
    double B = -2.0 * y2;
    double C = x2 * x2 + y2 * y2 + r1 * r1 - r2 * r2;

    double den = A * A + B * B;
    double x0 = -A * C / den;
    double y0 = -B * C / den;
    double lhs = C * C;
    double rhs = r1 * r1 * den;

    if (lhs > rhs + EPS)
        return res;

    if (abs(lhs - rhs) < EPS) {
        res.points.push_back({x0 + c1.x, y0 + c1.y});
        return res;
    }

    double mult = sqrt((rhs - lhs) / den) / sqrt(den);
    point p = {x0 + B * mult, y0 - A * mult};
    point q = {x0 - B * mult, y0 + A * mult};
    p.x += c1.x; p.y += c1.y;
    q.x += c1.x; q.y += c1.y;
    res.points.push_back(p);
    res.points.push_back(q);
    return res;
}
```

Bu kod [aylana va chiziq kesishmasi](circle-line-intersection.md) formulasini bevosita ichida qo‘llaydi. Amaliy loyihada ikki masala uchun bitta yordamchi funksiyadan foydalanish mumkin.

## Alternativ geometrik formula

Markazlar orasidagi masofa $d$ bo‘lsin. Birinchi markazdan markazlar chizig‘i bo‘ylab umumiy xordaning o‘rtasigacha masofa

$$
a=\frac{r_1^2-r_2^2+d^2}{2d}
$$

va xordning yarim uzunligi

$$
h=\sqrt{r_1^2-a^2}
$$

bo‘ladi. Birlik vektor $\mathbf e=(c_2-c_1)/d$ va unga perpendikulyar $\mathbf e_\perp=(-e_y,e_x)$ orqali nuqtalar

$$
p=c_1+a\mathbf e+h\mathbf e_\perp,
\qquad
q=c_1+a\mathbf e-h\mathbf e_\perp
$$

topiladi. Bu formula ham $O(1)$ vaqtda ishlaydi, ammo barcha degenerativ holatlar oldindan ajratilishi kerak.

# Ikki aylanaga umumiy urinmalar

Ikki aylana berilgan. Ikkalasiga bir vaqtda urinadigan barcha to‘g‘ri chiziqlarni topish kerak. Algoritm aylanalardan biri yoki ikkalasi radiusi nol bo‘lgan nuqtaga degeneratsiyalangan holatda ham ishlaydi; shu sababli u berilgan nuqtadan aylanaga urinmalarni topish uchun ham qo‘llanadi.

## Umumiy urinmalar soni

Ikki aylananing umumiy urinmalari soni $0,1,2,3,4$ yoki cheksiz bo‘lishi mumkin. Ustma-ust tushgan aylanalar cheksiz ko‘p umumiy urinmaga ega. Bir aylana ikkinchisining ichida yotsa, odatda umumiy urinma yo‘q; ichki tomondan tegsa bitta urinma mavjud.

Umumiy holatda to‘rtta urinma bo‘ladi: ikkita tashqi va ikkita ichki urinma. Aylanalar tegishganda ayrim urinmalar ustma-ust tushadi, shuning uchun turli geometrik chiziqlar soni uch yoki bittaga kamayishi mumkin. Quyidagi algebraik algoritm to‘rtta ishora kombinatsiyasini ko‘radi; degenerativ holatda qaytarilgan ayrim chiziqlar bir xil bo‘lishi mumkin.

## Algoritm

Soddalik uchun birinchi aylana markazini $(0,0)$ ga siljitamiz. Uning radiusi $r_1$, ikkinchi aylana markazi $v=(v_x,v_y)$ va radiusi $r_2$ bo‘lsin. Izlanayotgan chiziq

$$
ax+by+c=0
$$

ko‘rinishda va normallashgan:

$$
a^2+b^2=1.
$$

Chiziqning koordinatalar boshigacha masofasi $|c|$, ikkinchi markazgacha masofasi esa $|av_x+bv_y+c|$. Urinmalik shartlari:

$$
|c|=r_1,
\qquad
|av_x+bv_y+c|=r_2.
$$

Modullarni to‘rtta usulda ochamiz. $d_1=\pm r_1$, $d_2=\pm r_2$ deb olsak,

$$
a^2+b^2=1,
\qquad c=d_1,
\qquad av_x+bv_y+c=d_2.
$$

$r=d_2-d_1$ va $z=v_x^2+v_y^2$ belgilashlardan keyin yechimlardan bir oilasi:

$$
a=\frac{rv_x+v_y\sqrt{z-r^2}}{z},
\qquad
b=\frac{rv_y-v_x\sqrt{z-r^2}}{z},
\qquad c=d_1.
$$

$z-r^2<0$ bo‘lsa, shu ishora kombinatsiyasi uchun urinma mavjud emas. Kvadrat ildiz nol bo‘lsa, ikkita algebraik yechim bitta chiziqqa birlashadi.

Asl birinchi markaz $(x_0,y_0)$ bo‘lsa, koordinatalarni orqaga siljitish uchun

$$
c\leftarrow c-a x_0-b y_0
$$

qilinadi.

## Implementatsiya

```cpp
struct pt {
    double x, y;

    pt operator-(pt p) {
        pt res = {x - p.x, y - p.y};
        return res;
    }
};

struct circle : pt {
    double r;
};

struct line {
    double a, b, c;
};

const double EPS = 1E-9;

double sqr(double a) {
    return a * a;
}
```

Yordamchi funksiya bitta $(d_1,d_2)$ ishora kombinatsiyasiga mos urinmani qo‘shadi:

```cpp
void tangents(pt c, double r1, double r2, vector<line>& ans) {
    double r = r2 - r1;
    double z = sqr(c.x) + sqr(c.y);
    double d = z - sqr(r);
    if (d < -EPS)
        return;
    d = sqrt(abs(d));
    line l;
    l.a = (c.x * r + c.y * d) / z;
    l.b = (c.y * r - c.x * d) / z;
    l.c = r1;
    ans.push_back(l);
}
```

Asosiy funksiya radiuslarning barcha ishora variantlarini ko‘radi va chiziqlarni asl koordinatalarga qaytaradi:

```cpp
vector<line> tangents(circle a, circle b) {
    vector<line> ans;
    for (int i = -1; i <= 1; i += 2)
        for (int j = -1; j <= 1; j += 2)
            tangents(b - a, a.r * i, b.r * j, ans);
    for (size_t i = 0; i < ans.size(); ++i)
        ans[i].c -= ans[i].a * a.x + ans[i].b * a.y;
    return ans;
}
```

Agar markazlar ustma-ust tushsa, `z == 0` bo‘lib, formulada bo‘lish mumkin emas. Bu holat alohida tekshiriladi: radiuslar teng bo‘lsa cheksiz ko‘p urinma, teng bo‘lmasa umumiy urinma yo‘q.

Degenerativ holatlarda bir xil chiziq bir necha marta chiqishi mumkin. Faqat turli geometrik chiziqlar kerak bo‘lsa, normallashtirilgan koeffitsiyentlarni `EPS` bilan taqqoslab takrorlarini olib tashlash lozim.

